<?php if($transferOrder===''&&$transferState['can_write']):?><section class="card" data-transfer-list><h2><?=e($tr('Alle bisherigen Überweisungsaufträge dieser Rechnung'))?></h2><form method="get"><?=hidden('view','finance').hidden('tab','receipts').hidden('entry',$transferEntry)?><label><?=e($tr('Ganze Auftragssuche'))?><?php $trField('transfer_q',$trRaw($_GET,'transfer_q'));?></label><label><?=e($tr('Auftragsstatus'))?><select class="form-control" name="transfer_state"><option value=""><?=e($tr('Alle Status'))?></option><?php $status=$trRaw($_GET,'transfer_state');if($status!==''&&!isset($trStates[$status])):?><option selected value="<?=e($status)?>"><?=e($status)?></option><?php endif;foreach($trStates as$value=>$label):?><option value="<?=e($value)?>"<?=$status===$value?' selected':''?>><?=e($tr($label))?></option><?php endforeach ?></select></label><label><?=e($tr('Auftragsseite'))?><?php $trField('transfer_page',$trRaw($_GET,'transfer_page','1'));?></label><button class="btn btn-outline theme-secondary"><?=e($tr('Ganze Suche und genaue Seite anzeigen'))?></button></form>
