<section class="card" data-transfer-history><h2><?=e($tr('Eigene frühere Überweisungsentscheidungen'))?></h2><form method="get"><?=hidden('view','finance').hidden('tab','receipts').hidden('entry',$transferEntry)?><?php if($transferOrder!=='')echo hidden('transfer_order',$transferOrder);?><label><?=e($tr('Ganze Entscheidungssuche'))?><?php $trField('transfer_history_q',$trRaw($_GET,'transfer_history_q'));?></label><label><?=e($tr('Entscheidungsseite'))?><?php $trField('transfer_history_page',$trRaw($_GET,'transfer_history_page','1'));?></label><button class="btn btn-outline theme-secondary"><?=e($tr('Eigene ursprüngliche Entscheidungen durchsuchen'))?></button></form>
